-- Spell icon style: the class tabs (Shaman buff and totem tabs, Paladin seals and auras, Warrior stances) wear
-- either the game's own icon ("stock") or a baked STUwave gradient version of it ("gradient", the default),
-- chosen by the setting `icons.spellstyle`.
--
-- The art is Media/Textures/spellart_<icon>.tga and the lookup is FS.SpellArtData (generated by
-- tools/assets/synthwave_icons.py --bake-spells): the icon FILE ID the client reports for a spell, or the lower case
-- icon file name when it answers with an Interface\Icons path, to the art name. Anything not in the table keeps its
-- stock texture, so a tile is never blank: Resolve returns what it was given whenever it has nothing better.
--
-- Callers do not draw the texture themselves: FrameHelpers.SetSpellIcon(tex, stock) goes through Set, which writes the
-- resolved texture and remembers the stock one per texture, so a change of the setting repaints every bound texture
-- at once. Texture writes only; legal in combat, and a write that errors is skipped.
local _, FS = ...

local SpellArt = {}
FS.SpellArt = SpellArt

local MEDIA = "Interface\\AddOns\\forever-stuwave\\Media\\Textures\\"

SpellArt.SETTING = {
    key = "icons.spellstyle", default = "gradient", label = "Spell icon style",
    tip = "Gradient draws the spell icons on the class tabs (Shaman buffs and totems, Paladin seals and auras, "
        .. "Warrior stances) in the STUwave colours. Stock shows the game's own icons.",
}
SpellArt.STYLES = { "gradient", "stock" }

if FS.Config and FS.Config.RegisterDefault then
    FS.Config.RegisterDefault(SpellArt.SETTING.key, SpellArt.SETTING.default)
end

-- "gradient" unless the setting says "stock"; any other value is the default.
function SpellArt.Style()
    local config = FS.Config
    local value = config and config.Get and config.Get(SpellArt.SETTING.key)
    if value == "stock" then return "stock" end
    return "gradient"
end

local function ArtName(stock)
    local data = FS.SpellArtData
    if not data then return nil end
    if type(stock) == "number" then return data.byFile[stock] end
    if type(stock) == "string" then
        local name = stock:lower():match("([^\\/]+)$")
        if name then return data.byName[name:gsub("%.%a+$", "")] end
    end
    return nil
end

-- The texture to draw for the stock one the client gave: the baked file when the style is gradient and there is
-- one, else `stock` untouched (nil, a secret value and anything unknown included).
function SpellArt.Resolve(stock)
    if stock == nil or (FS.IsSecret and FS.IsSecret(stock)) then return stock end
    if SpellArt.Style() ~= "gradient" then return stock end
    local name = ArtName(stock)
    if name then return MEDIA .. "spellart_" .. name .. ".tga" end
    return stock
end

-- texture -> the stock texture it was last given. Weak keys: a dropped button frees its entry.
local bound = setmetatable({}, { __mode = "k" })

-- true once any tab has bound an icon: the settings page offers the choice only then.
function SpellArt.Applies()
    return next(bound) ~= nil
end

local function Write(tex, stock)
    pcall(tex.SetTexture, tex, SpellArt.Resolve(stock))
end

-- Draws `stock` on `tex` in the current style and remembers it for a later repaint.
function SpellArt.Set(tex, stock)
    bound[tex] = stock
    Write(tex, stock)
end

-- Stops following the setting (the texture is about to show something that is not a spell icon).
function SpellArt.Forget(tex)
    bound[tex] = nil
end

function SpellArt.Repaint()
    for tex, stock in pairs(bound) do Write(tex, stock) end
end

if FS.Config and FS.Config.OnChange then
    FS.Config.OnChange(SpellArt.SETTING.key, SpellArt.Repaint)
end
